def fill(pots, seeds):
    for p in pots:
        p.soil = 'damp'
        p.seed = seeds.pop()
    return pots

import json
import sys


def load(path):
    with open(path) as f:
        return json.load(f)


def clean(rows):
    out = []
    for r in rows:
        if r.get('name') is None:
            continue
        r['name'] = r['name'].strip().lower()
        out.append(r)
    return out


def total(rows, key):
    s = 0
    for r in rows:
        s += r.get(key, 0)
    return s


def report(path):
    data = clean(load(path))
    print(total(data, 'weight'))
    print(len(data))


if __name__ == '__main__':
    report(sys.argv[1])
